@use "sass:map";
@use "theme" as theme with ($radius: 12px);

$space: 1rem !default;
$palette: (ink: #242938, accent: #8250df);

@mixin card($padding: $space, $radius: 12px) {
  padding: $padding;
  border-radius: $radius;
  color: map.get($palette, ink);
  @content;
}

.card {
  @include card($padding: 1.5rem) {
    background: #f6f3ff;
  }
  font: {
    size: 1rem;
    weight: 600;
  }
  &:hover { color: map.get($palette, accent); }
}

/* Basic CSS shared by both grammars. */
.card, #featured {
  display: flex;
  gap: 1rem;
  padding: 24px;
  color: #242938;
  background: linear-gradient(135deg, #fff, #eee);
  border: 1px solid rgba(0, 0, 0, 0.1);
  font-family: "Inter", sans-serif;
}

.card:hover > a::before {
  content: "Hello, SCSS!";
  opacity: 0.8;
}

@media screen and (min-width: 768px) {
  .card { max-width: 60rem; }
}

@use "sass:map";
@use "tokens" as tokens;

$gap: 8px !default;
$enabled: true;
$empty: null;
$palette: (
  ink: #242938,
  accent: #8250df,
  states: (hover: #6639ba, focus: #0969da),
);

tokens.$gap: 12px;

.card {
  $gap: 16px !global;
  padding: $gap;
  color: map.get($palette, states, hover);
  opacity: if($enabled, 1, .5);
}

@forward "tokens" as token-* show $token-gap, token-scale with (
  $gap: 1rem !default,
  $accent: #8250df,
);
@use "sass:math";
@use "theme" as theme with ($radius: 12px);
@use "utilities" as *;

.card {
  width: math.percentage(math.div(1, 3));
  border-radius: theme.$radius;
  @include theme.surface($tone: "quiet");
  @include stack($gap: 1rem);
}

@use "sass:list";

@mixin ring($color: #8250df, $width: 2px) {
  outline: $width solid $color;
}

@mixin apply($sizes...) {
  @each $size in $sizes {
    @content($size);
  }
}

$args: (#0969da, 3px);
.card {
  @include ring($args...);
  @include apply(4px, 8px, 12px) using ($space) {
    margin: $space;
  }
  @include ring($width: 1px, $color: #242938);
}

@function rhythm($step, $base: 8px) {
  @if $step > 2 and $base != 0 {
    @return $step * $base;
  } @else if $step == 0 {
    @return 0;
  } @else {
    @return $base;
  }
}

@for $i from 1 to 4 {
  .gap-#{$i} { gap: rhythm($i); }
}
@for $i from 1 through 3 {
  .order-#{$i} { order: $i; }
}
@each $name, $color in (ink: #242938, accent: #8250df) {
  .text-#{$name} { color: $color; }
}
$i: 2;
@while $i > 0 { $i: $i - 1; }

$prefix: "card";
$side: left;
$asset: "hero";

.#{$prefix} {
  margin-#{$side}: 1rem;
  content: "Hello #{$prefix}!\a Next line";
  --label: "before #{$prefix} after";
  background: url("/img/#{$asset}.svg");
  &--active { color: #8250df; }
}

/* A block comment with #{$prefix} text. */
// A line comment with $side and .card syntax.

@namespace svg url("http://www.w3.org/2000/svg");

.a .b:hover { color: red; }
a[href^="https" i]::after { content: "external"; }
svg|a, *|button, |input { cursor: pointer; }

.card {
  &:is(.active, :focus-visible) { outline: 2px solid; }
  &:where(.muted, [disabled]) { opacity: .5; }
  &:has(> img) { display: grid; }
  &:nth-child(2n + 1 of .card, .tile) { order: 1; }
  & + & { margin-top: 1rem; }
}

%surface { background: #fff; }

.card {
  @extend %surface !optional;
  font: {
    family: "Inter", sans-serif;
    size: 1rem;
    weight: 600;
  }
  border: 1px solid {
    color: #8250df;
    radius: 12px;
  }
  > .title { margin: 0; }
  &:hover { color: #6639ba; }
  @at-root .global-title { font-weight: 700; }
}

@media (400px < width <= 1200px) and (hover) {
  .card { padding: 2rem; }
}
@media not (hover) {
  .card { padding: 1rem; }
}
@supports (display: grid) and selector(:has(> img)) {
  .gallery { display: grid; }
}
@container sidebar (inline-size > 30rem) {
  .card { gap: 2cqi; }
}
@container style(--theme: dark) {
  .card { background: #242938; }
}

$gap: 1rem;

.card {
  --literal: $gap;
  --resolved: #{$gap};
  --payload: { color: red; list: [one, (two, three)]; };
  --space: var(--missing,);
  margin: var(--space, 1rem);
  background: url(https://example.com/assets/a.svg?v=1#icon);
  mask: url(data:image/svg+xml;base64,PHN2Zz48L3N2Zz4=);
  --message: "braces { } and // stay inside the string";
}

@layer reset, components;

@property --progress {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}

@layer components {
  @scope (.card) to (.nested-card) {
    :scope { --progress: .5; }
    .title { color: #8250df; }
  }
}

@starting-style {
  .dialog { opacity: 0; }
}
@position-try --below {
  inset-area: bottom;
}

@keyframes enter {
  from { opacity: 0; transform: translateY(-.5rem); }
  50% { opacity: .5; }
  to { opacity: 1; transform: translateY(0); }
}

.card {
  width: clamp(10rem, 50vw, 60rem);
  height: calc(100% - var(--gap, 1rem));
  rotate: calc(pi * 1rad);
  opacity: 1e-1;
  font: 12px/1.5 sans-serif;
  grid-area: 1/2/3/4;
  color: oklch(65% 0.2 270 / .8);
  animation: enter 200ms ease-out;
}

$紫色: #8250df;
$label: "Hello 🦊";

.卡片, .caf\e9, #item\:one {
  color: $紫色;
  content: "#{$label} / \"quoted\" / \a new line";
  --escaped: "\1F98A";
  font-family: "中文", sans-serif;
}

/* 🦊 before the final rule tests character positions. */
.sentinel { width: 12px; color: #abc; }
